#!/usr/bin/env elixir
# GENERATED by the foreman-jobsite-template skill -- one jobsite, one agent turn.
#
# Run with plain `elixir` (OTP 27+). No Foreman checkout, no database, nothing in
# the project's mix.exs: Mix fetches foreman_client and that is the whole dep.
# Use the repo's own copy while iterating: change the Mix.install tuple above to
# {:foreman_client, path: "/path/to/foreman/packages/foreman_client"}.
#
#   export FOREMAN_API_TOKEN=...      # the server's bearer token (required)
#   export FOREMAN_PROJECT_ID=...     # optional: overrides the baked-in project_id
#   elixir this-script.exs
#
# FOREMAN_API_URL defaults to http://127.0.0.1:4766.
#
# The AGENT runs on the server, in the server's checkout of the registered
# project. This script only sends the spec and waits.

Mix.install([{:foreman_client, github: "Sunstone-Partners/foreman", sparse: "packages/foreman_client"}])
# NOTE: the bundled templates under
# packages/foreman_cli/cmd/foreman/templates/ use github:
# "ldangelo/foreman" for the same package. `ldangelo/foreman` is where this
# session's Mix fetch resolved; the org remote named in AGENTS.md is
# Sunstone-Partners/foreman. Both were never verified side by side — if the
# fetch fails, try the other, or point at a checkout with
# {:foreman_client, path: ".../packages/foreman_client"}.

# Fill in every REPLACE-WITH-* value below before running; an unfilled
# placeholder is refused by the server as spec_project_not_found or
# spec_provider_invalid, not silently defaulted.
spec = %{
  "project_id" => System.get_env("FOREMAN_PROJECT_ID") || "REPLACE-WITH-A-REGISTERED-PROJECT-ID",
  "name" => "my-feature",
  "prompt" => """
  Replace this with the prompt text. A remote spec has no file channel: prompt_file
  is refused, so the instructions travel as these bytes.
  """,
  "strategy" => %{"branch" => "agent/my-feature"},
  "sandbox" => "docker",
  "agent" => %{
    "provider" => "pi",
    "model" => "REPLACE-WITH-A-MODEL",
    "approval_mode" => "auto_approve"
  }
}

client = Foreman.Client.new()

case Foreman.Client.run(client, spec) do
  {:ok, jobsite} ->
    IO.puts("jobsite_id=#{jobsite["id"]}")
    IO.puts("status=#{jobsite["status"]}")
    IO.puts("branch=#{jobsite["branch"]} commits=#{length(jobsite["commits"] || [])}")

    if output = jobsite["output"] do
      IO.puts("\n--- agent output ---\n#{output}")
    end

  {:error, {:jobsite, jobsite}} ->
    IO.puts(:stderr, "jobsite did not complete: status=#{inspect(jobsite["status"])}")
    IO.puts(:stderr, "detail: #{inspect(Map.get(jobsite, "error") || Map.get(jobsite, "failure") || jobsite)}")
    IO.puts(:stderr, "branch=#{inspect(jobsite["branch"])} -- inspect the worktree before retrying")
    System.halt(1)

  {:error, {status, body}} ->
    # A spec rejected by Jobsite.Spec.from_json lands here: the body carries the
    # server's error code (spec_unknown_key, spec_push_requires_branch, ...).
    # A 401 means the request never reached the validator.
    IO.puts(:stderr, "server rejected the request: HTTP #{status}")
    IO.puts(:stderr, :json.encode(body))
    System.halt(1)

  {:error, {:transport, reason}} ->
    IO.puts(:stderr, "cannot reach the server: #{inspect(reason)}")
    IO.puts(:stderr, "FOREMAN_API_URL=#{System.get_env("FOREMAN_API_URL", "http://127.0.0.1:4766")}")
    IO.puts(:stderr, "is foreman_server running, and is jobsites.allow_remote_start true?")
    System.halt(1)

  {:error, reason} ->
    IO.puts(:stderr, "unexpected failure: #{inspect(reason)}")
    System.halt(1)
end
